package dominoes

// Domino represents a single domino stone, with two halves.
type Domino [2]int

// MakeChain orders the given dominoes into a closed chain: each stone's halves
// match its neighbours, and the two free ends (first and last stones) match
// each other. It returns the chain and true on success, or nil and false when
// no such chain exists.
func MakeChain(input []Domino) ([]Domino, bool) {
	n := len(input)
	if n == 0 {
		return []Domino{}, true
	}

	// Necessary conditions for a closed chain to exist: every value must occur
	// an even number of times (even degree at every vertex), and the stones
	// must form a single connected component. These are not sufficient on
	// their own, but they let us reject impossible inputs quickly.
	deg := make(map[int]int)
	for _, d := range input {
		deg[d[0]]++
		deg[d[1]]++
	}
	for _, v := range deg {
		if v%2 != 0 {
			return nil, false
		}
	}

	adj := make(map[int]map[int]bool)
	for _, d := range input {
		if adj[d[0]] == nil {
			adj[d[0]] = make(map[int]bool)
		}
		if adj[d[1]] == nil {
			adj[d[1]] = make(map[int]bool)
		}
		adj[d[0]][d[1]] = true
		adj[d[1]][d[0]] = true
	}
	start := input[0][0]
	seen := map[int]bool{start: true}
	stack := []int{start}
	for len(stack) > 0 {
		v := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		for w := range adj[v] {
			if !seen[w] {
				seen[w] = true
				stack = append(stack, w)
			}
		}
	}
	for v := range adj {
		if !seen[v] {
			return nil, false
		}
	}

	// Search for the chain by backtracking. Because the chain is a cycle we
	// can fix input[0] as the first stone without loss of generality.
	used := make([]bool, n)
	chain := make([]Domino, 0, n)

	var backtrack func(current int) bool
	backtrack = func(current int) bool {
		if len(chain) == n {
			return chain[len(chain)-1][1] == chain[0][0]
		}
		for i := 0; i < n; i++ {
			if used[i] {
				continue
			}
			d := input[i]
			if d[0] == current {
				used[i] = true
				chain = append(chain, Domino{d[0], d[1]})
				if backtrack(d[1]) {
					return true
				}
				chain = chain[:len(chain)-1]
				used[i] = false
			}
			if d[1] == current && d[1] != d[0] {
				used[i] = true
				chain = append(chain, Domino{d[1], d[0]})
				if backtrack(d[0]) {
					return true
				}
				chain = chain[:len(chain)-1]
				used[i] = false
			}
		}
		return false
	}

	first := input[0]
	for _, orient := range [2]int{0, 1} {
		used[0] = true
		chain = append(chain, Domino{first[orient], first[1-orient]})
		if backtrack(first[1-orient]) {
			return chain, true
		}
		chain = chain[:len(chain)-1]
		used[0] = false
	}

	return nil, false
}
